[
  {
    "find": "The US parser now drops a default bare number when a `CTH`/`CR` county ref of the same number (space or hyphen, same modifier) is present, in either order.",
    "replace": "The US parser now drops a default bare number when a county ref that uses `CTH` or `CR` and has the same number is also present. This applies in either order; that prefix can be separated from the number by a space or a hyphen, and the modifier must be the same.",
    "type": "hard-clause",
    "reason": "The original packs several conditions into one sentence with a slash and a parenthetical, so the reader has to unpack what must be present and in what order."
  },
  {
    "find": "Other countries and the shared parser are unchanged, so separate routes like `e-road/E 12;NO:RV/12` and modified ones like `MEX 2 D` keep their shields; relation shields with a network style (e.g. `US:WI/12`) are kept too.",
    "replace": "Other countries and the shared parser are unchanged. Separate routes like `e-road/E 12;NO:RV/12` and modified routes like `MEX 2 D` keep their shields, and relation shields that include a network, such as `US:WI/12`, are also kept.",
    "type": "hard-clause",
    "reason": "The sentence stacks the unchanged scope and several preserved cases into one semicolon-joined clause, and 'ones' plus 'network style' make the reader infer what is being kept."
  },
  {
    "find": "Tested with `indexer_tests`:",
    "replace": "I tested this with `indexer_tests`.",
    "type": "telegraphic",
    "reason": "The original starts with a past participle and no subject, so it reads like a test-log label rather than a sentence."
  },
  {
    "find": "Norway/Mexico",
    "replace": "Norway and Mexico",
    "type": "telegraphic",
    "reason": "The slash stands in for 'and', forcing the reader to decode the case list."
  }
]

[
  {
    "find": "(also `target_sw=node.js`)",
    "replace": "(with `target_sw=node.js` as well)",
    "type": "telegraphic",
    "reason": "The parenthetical drops the preposition, so the technical detail reads like a label rather than a phrase."
  },
  {
    "find": "none of its CVEs were matched",
    "replace": "none of the package's CVEs were matched",
    "type": "unclear-reference",
    "reason": "'its' could refer to the CPE or the package; make the owner explicit."
  },
  {
    "find": "(translations are first-match)",
    "replace": "(the first matching translation wins)",
    "type": "coined-label",
    "reason": "'first-match' is a compressed label; the sentence is easier to follow as a plain rule."
  },
  {
    "find": "Not included: the Homebrew `claude-code` cask.",
    "replace": "This change does not include the Homebrew `claude-code` cask.",
    "type": "telegraphic",
    "reason": "The colon label omits the subject and verb; write it as a full sentence."
  },
  {
    "find": "Homebrew software gets `target_sw=macos` in the generated CPE, and every claude_code CVE configuration I checked is pinned to `target_sw=node.js`, so a vendor/product rule alone would not surface those CVEs.",
    "replace": "For Homebrew software, the generated CPE has `target_sw=macos`. Every claude_code CVE configuration I checked is pinned to `target_sw=node.js`, so a rule that matches only on vendor and product would not find those CVEs.",
    "type": "hard-clause",
    "reason": "The original packs three ideas into one chain and uses compressed terms like 'vendor/product rule' and 'surface'; splitting it makes the causal step easier to follow."
  }
]

[
  {
    "find": "Refactors spanning multiple packages land",
    "replace": "Refactors that span multiple packages land",
    "type": "hard-clause",
    "reason": "The reduced relative clause makes the subject and verb harder to parse."
  },
  {
    "find": "eliminating version-skew coordination",
    "replace": "so you no longer need to coordinate version mismatches",
    "type": "coined-label",
    "reason": "Version-skew coordination is a compressed label for coordinating mismatched versions."
  },
  {
    "find": "One CI configuration, one linting setup, consistent dependency versions.",
    "replace": "You have one CI configuration, one linting setup, and consistent dependency versions.",
    "type": "telegraphic",
    "reason": "The list has no finite verb or conjunction, so it reads like notes rather than a sentence."
  },
  {
    "find": "Git performance at scale, code ownership mapping, and selective test execution all require dedicated effort.",
    "replace": "Keeping Git fast at scale, mapping code ownership, and selecting which tests to run all require dedicated effort.",
    "type": "buried-verb",
    "reason": "The actions are hidden in noun phrases, making the requirement abstract."
  },
  {
    "find": "a monorepo tends to pay dividends",
    "replace": "a monorepo tends to be worth it",
    "type": "jargon",
    "reason": "Pay dividends is a financial metaphor; worth it states the value judgment plainly."
  }
]

[
  {
    "find": "Start and end at the same times",
    "replace": "Start and end work at the same times",
    "type": "telegraphic",
    "reason": "The sentence drops the object of 'start' and 'end,' so the reader has to infer that it means work."
