    "find": "We're excited to unveil",
    "replace": "We're introducing",
    "type": "empty-words",
    "reason": "The excited-to-unveil preamble is hype and does not add information."
  },
  {
    "find": "a reimagined export experience",
    "replace": "a redesigned export feature",
    "type": "coined-label",
    "reason": "Reimagined export experience is a compressed label; say it is a redesigned export feature."
  },
  {
    "find": "that empowers teams to seamlessly operationalize their reporting workflows",
    "replace": "that lets teams run their reporting workflows",
